"""수용된 QG1 기준에서 QG2 입력/선택과 측정 어댑터 writer를 서로 다른 경로로 분리한다."""
import hashlib,json,pathlib,shutil,subprocess
R=pathlib.Path(__file__).resolve().parents[1]
load=lambda rel:json.loads((R/rel).read_text(encoding='utf-8'))
assert load('artifacts/qg1-acceptance.json')['decision']=='ACCEPTED_SHARED_CORE_FACADE_AND_QUICK_RESULT_CONTRACT_ONLY'
source_files={**load('artifacts/qg0-inspector-baseline.json')['protected_inspector_sha256'],**load('artifacts/qg1-acceptance.json')['source_sha256']}
contract={'version':'qg2a-0.1','scope':'QG2 시작: 순수 다중대상 입력/선택 계획 및 기존 실제 프로브 결과의 Quick 매핑. 네트워크 실행기/DNS/Traceroute/GUI/EXE 완료 아님','input_module':'network_core::targets','measurement_module':'network_core::measurements','input_api':{'QuickTarget':['host:String','port:u16','raw_input:String'],'QuickOptions':['tcp_timeout_ms:u64','concurrency:usize','selected_features:Vec<QuickFeature>'],'PlannedTarget':['target:QuickTarget','features:Vec<QuickFeature>','requires_resolution:bool'],'QuickPlan':['targets:Vec<PlannedTarget>','tcp_timeout_ms:u64','icmp_timeout_ms:Option<u64>','concurrency:usize','limitations:Vec<String>'],'InputError':['line:usize','message:String'],'functions':['parse_target_pair(host:&str,port:&str)->Result<QuickTarget,Vec<InputError>>','parse_target_list(input:&str)->Result<Vec<QuickTarget>,Vec<InputError>>','build_quick_plan(targets:&[QuickTarget],options:&QuickOptions)->Result<QuickPlan,Vec<InputError>>'],'limits':{'max_unique_targets':100,'max_input_bytes':32768,'default_concurrency':4,'max_concurrency':4,'default_tcp_timeout_ms':3000,'tcp_timeout_range_ms':[1,60000],'icmp_timeout_ms':'selected Ping이면 min(TCP timeout,2000)와 한계명시; 없으면None','default_features':['tcp_connect','icmp_ping']},'domain_resolution':'domain + TCP/Ping/Trace/local_network 중선택시 필수OS주소해석 필요; 상세DNS선택과별도. IP직접입력은상세DNS미선택시required_resolution false. 실제DNS수행은이번API범위아님','selection':'선택없으면계획target별features빈값/총probe계획0;미선택기능을자동추가하지않음. 입력/옵션deepclone snapshot,중복feature거부'},'measurement_api':{'functions':['icmp_to_quick_result(ctx:&QuickContext,measurement:&IcmpMeasurement)->Result<QuickResult,Vec<String>>','host_to_quick_result(ctx:&QuickContext,snapshot:&HostSnapshot,elapsed_ms:Option<u64>)->Result<QuickResult,Vec<String>>'],'icmp_mapping':{'REPLY':['PASS','OBSERVED'],'TIMEOUT':['FAIL','OBSERVED'],'UNREACHABLE':['FAIL','OBSERVED'],'LOCAL_ERROR':['UNKNOWN','OBSERVED'],'CANCELLED':['UNKNOWN','UNKNOWN'],'UNAVAILABLE':['UNKNOWN','UNKNOWN'],'unrecognized':['UNKNOWN','UNKNOWN']},'raw_preservation':'details {outcome,limitations,raw_measurement} 정확3필드,기존DTO raw전체불변. ICMP ip_status와error_code구분;u32OSerror가i32초과면topnull·rawu32보존및한계. 메타데이터필수키/null/시간은기존validate_quick_result재사용','host_mapping':'components를기존AdapterEntry/RouteEntry/SelectedRouteEntry로검사.모두유효+errors없음 PASS/OBSERVED;일부유효row+errors/실패 WARN/OBSERVED;모두수집실패/불량 UNKNOWN/UNKNOWN.임의일반인부분데이터를원격연결PASS로오인금지','target_attribution':'ICMP measurement.target IpAddr와ctx literal IP일치검사;Host selected_route.target SocketAddr아닌IpAddr와ctx literal IP일치검사. domain은resolver조회안하고실측주소만resolved_ip로유도. host에target이없으면null,ctx주소로발명금지'},'safety':'기본테스트실제네트워크/OS/프로세스/파일쓰기0. live시험은부모가별도수행. 운영IP문서예시는검사승인아님. 기존npi-*와Quick결과schema변경금지'}
refs=R/'.harness/references';path=refs/'qg2a-contract.json';assert not path.exists();path.write_text(json.dumps(contract,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for role,module in [('qg2input','targets'),('qg2measure','measurements')]:
 w=R/'.worktrees'/role;assert not w.exists();p=subprocess.run(['git','-C',str(R),'worktree','add','-b','ai-pro/'+role,str(w),'2118fa6'],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=60);assert p.returncode==0,p.stderr
 for rel,sha in source_files.items():
  data=(R/rel).read_bytes();assert hashlib.sha256(data).hexdigest()==sha,rel;dst=w/rel;dst.parent.mkdir(parents=True,exist_ok=True);dst.write_bytes(data)
 for folder in ['docs/requirements','docs/quick-check']:
  for p in (R/folder).glob('*.md'):
   dst=w/p.relative_to(R);dst.parent.mkdir(parents=True,exist_ok=True);dst.write_bytes(p.read_bytes())
 for rel in ['contracts/quick-check-interface-v0.1.json','Cargo.toml','Cargo.lock']:
  dst=w/rel;dst.parent.mkdir(parents=True,exist_ok=True);dst.write_bytes((R/rel).read_bytes())
 dest=w/'.harness/references';dest.mkdir(parents=True,exist_ok=True);shutil.copyfile(path,dest/path.name);shutil.copyfile(R/'artifacts/qg1-acceptance.json',dest/'qg1-acceptance.json')
 lib=w/'crates/network-core/src/lib.rs';text=lib.read_text(encoding='utf-8');lib.write_text(text+'\n// QG2 전용 writer가 생성할 새 모듈. 기존 facade와 Inspector 구현은 보존한다.\npub mod '+module+';\n',encoding='utf-8',newline='\n')
 for args in [['add','Cargo.toml','Cargo.lock','crates','ui/src','ui/scripts','ui/package.json','ui/package-lock.json','PRD.md','start_npi.bat','contracts','schemas','fixtures','docs/requirements','docs/quick-check'],['-c','core.autocrlf=false','commit','-m','chore: prepare accepted QG1 baseline for '+role]]:
  p=subprocess.run(['git','-C',str(w),*args],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=40);assert p.returncode==0,p.stderr
 p=subprocess.run(['git','-C',str(w),'status','--porcelain'],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=20);assert not p.stdout,p.stdout
 print(role,'수용QG1기준 clean 준비; 신규모듈은해당writer의출력으로생성예정')
